function getCameraForViewType(viewType, width = 1, height = 1, miiHeight = 1) {
  const aspect = width / height;
  switch (viewType) {
    case ViewType.Face: {
      const fovy = 15;
      const camera = new THREE6.PerspectiveCamera(fovy, aspect, 0.1, 1000);
      camera.position.set(0, 34.5, 380);
      camera.lookAt(0, 34.3, 0);
      return camera;
    }
    case ViewType.MakeIcon: {
      const fovy = 9.8762;
      const camera = new THREE6.PerspectiveCamera(fovy, aspect, 500, 1000);
      camera.position.set(0, 34.5, 600);
      camera.lookAt(0, 34.5, 0);
      return camera;
    }
    case ViewType.IconFovy45: {
      const camera = new THREE6.PerspectiveCamera(45, aspect, 50, 1000);
      camera.position.set(0, 34, 110);
      camera.lookAt(0, 34, 0);
      return camera;
    }
    case ViewType.AllBody: {
      const fovy = 15;
      const camera = new THREE6.PerspectiveCamera(fovy, aspect, 50, 1500);
      camera.position.set(0, 50, 900);
      camera.lookAt(0, 105, 0);
      return camera;
    }
    case ViewType.AllBodySugar: {
      const fovy = 15;
      const camera = new THREE6.PerspectiveCamera(fovy, aspect, 50, 15000);
      const posStart = new THREE6.Vector3(0, 65, 550);
      const atStart = new THREE6.Vector3(0, 65, 0);
      const posEnd = new THREE6.Vector3(0, 75, 850);
      const atEnd = new THREE6.Vector3(0, 88, 0);
      const t = (miiHeight - 0.5) / (1.264 - 0.5);
      const pos = new THREE6.Vector3(posStart.x + t * (posEnd.x - posStart.x), posStart.y + t * (posEnd.y - posStart.y), posStart.z + t * (posEnd.z - posStart.z));
      const at = new THREE6.Vector3(atStart.x + t * (atEnd.x - atStart.x), atStart.y + t * (atEnd.y - atStart.y), atStart.z + t * (atEnd.z - atStart.z));
      camera.position.copy(pos);
      camera.lookAt(at);
      return camera;
    }
    case ViewType.CreditIcon: {
      const fovy = 15;
      const camera = new THREE6.PerspectiveCamera(fovy, aspect, 0.1, 1000);
      camera.position.set(-60, 34.5, 380);
      camera.lookAt(0, 34.3, 0);
      return camera;
    }
    default:
      throw new Error("getCameraForViewType: not implemented");
  }
}

