function renderTargetToDataURL(renderTarget, renderer, flipY = false, blob = true) {
  return new Promise((resolve) => {
    const scene = new THREE7.Scene;
    scene.background = null;
    const material = new THREE7.MeshBasicMaterial({
      side: THREE7.DoubleSide,
      map: renderTarget.texture,
      transparent: true
    });
    const plane = new THREE7.PlaneGeometry(2, 2);
    const mesh = new THREE7.Mesh(plane, material);
    scene.add(mesh);
    const camera = getIdentCamera(flipY);
    const prevTarget = renderer.getRenderTarget();
    const prevColorSpace = renderer.outputColorSpace;
    const size = new THREE7.Vector2;
    renderer.getSize(size);
    renderer.setRenderTarget(null);
    renderer.outputColorSpace = THREE7.ColorManagement ? THREE7.ColorManagement.workingColorSpace : null;
    renderer.setSize(renderTarget.width, renderTarget.height, false);
    renderer.render(scene, camera);
    function cleanup() {
      material.dispose();
      plane.dispose();
      scene.remove(mesh);
      renderer.outputColorSpace = prevColorSpace;
      renderer.setSize(size.x, size.y, false);
      renderer.setRenderTarget(prevTarget);
    }
    if (blob) {
      const ok = (blob) => {
        resolve({ type: "blob", result: blob });
        cleanup();
      };
      if (isWorker) {
        renderer.domElement.convertToBlob({ type: "image/png" }).then(ok);
      } else {
        renderer.domElement.toBlob(ok);
      }
    } else {
      const result = renderer.domElement.toDataURL("image/png");
      resolve({ type: "dataURL", result });
      cleanup();
    }
  });
}
async function renderTargetToDataTexture(renderTarget, renderer, flipY = false, filtering = true) {
  const { width, height } = renderTarget;
  let buf = new Uint8Array(width * height * 4);
  await renderer.readRenderTargetPixelsAsync(renderTarget, 0, 0, width, height, buf);
  const dataTexture = new THREE7.DataTexture(buf, width, height, THREE7.RGBAFormat, THREE7.UnsignedByteType);
  dataTexture.needsUpdate = true;
  if (flipY) {
    dataTexture.flipY = true;
  }
  if (filtering) {
    dataTexture.minFilter = THREE7.LinearFilter;
    dataTexture.magFilter = THREE7.LinearFilter;
  }
  return dataTexture;
}

