// src/class/3d/ClothingHelper.ts
async function clothingUpdate({
  gender,
  clothesType,
  renderer,
  bodyModel,
  shirtColor,
  pantsColor,
  shoesColor,
  facelineColor,
  clothesTextures,
  nBody,
  nLegs,
  bodyGroup,
  originalMaterial,
  customTexture,
  customTextureType,
  texResolution
}) {
  const THREE = _THREE();
  const suffix = gender == 1 ? "F" : "";
  const clothingEntry = clothesType;
  let key = `${bodyModel}_${ExtClothesList[clothingEntry]}${suffix}`;
  let shirtKey = key;
  async function loadClothingTexture(clothesKey) {
    let texture;
    switch (ClothesTypeList[clothingEntry]) {
      case 0 /* COLOR_MIXED */: {
        const colorMixR = new THREE.Vector4(...shirtColor, 1), colorMixG = new THREE.Vector4(...shoesColor, 1), colorMixB = new THREE.Vector4(...pantsColor, 1), colorMixA = new THREE.Color(facelineColor ? facelineColor : 16777215);
        console.log("Clothing Texture Key:", clothesKey);
        texture = await colorMixTexture(clothesTextures[clothesKey], colorMixR, colorMixG, colorMixB, colorMixA, renderer, texResolution);
        console.log("loaded shirt texture!");
        break;
      }
      case 1 /* TEXTURE_COLOR */: {
        texture = clothesTextures[clothesKey];
        break;
      }
      default:
        const errString = `An error occurred while loading clothing texture: Texture entry "${clothesKey}" doesn't exist in clothes table`;
        alert(errString);
        throw new Error(errString);
    }
    renderer.initTexture(texture);
    return texture;
  }
  let nBodyMat = nBody.material;
  let nLegsMat = nLegs.material;
  let isUsingShader = await isShaderMaterial();
  let clothesModulate = isUsingShader ? { modulateType: 9, modulateMode: 1, color: new THREE.Color(16777215) } : {};
  if (bodyModel !== "miitomo" /* Miitomo */) {
    if (clothesType === -1) {
      return;
    }
    const shirtTexture = await loadClothingTexture(shirtKey);
    const params = {
      ...clothesModulate,
      map: shirtTexture
    };
    const newBodyMat = new originalMaterial(params);
    nBody.material = newBodyMat;
    nLegs.material = newBodyMat;
  } else {
    if (clothesType === -1) {
      bodyGroup.traverse((object) => {
        if (object.isMesh !== true)
          return;
        const mesh = object;
        const suffix = gender === 1 ? "f" : "m";
        if (mesh.name === `body_${suffix}` || mesh.name === `legs_${suffix}`) {
          mesh.visible = true;
        } else {
          mesh.visible = false;
        }
      });
      return;
    }
    if (!ExtClothesMiitomoMeshAndTextureList[clothingEntry])
      throw new Error("No clothing entry for index " + clothingEntry);
    const entry = ExtClothesMiitomoMeshAndTextureList[clothingEntry];
    const list = Object.keys(entry);
    let promises = [];
    bodyGroup.traverse((object) => {
      if (object.isMesh !== true)
        return;
      const mesh = object;
      const entryMeshIndex = list.findIndex((key) => object.name === `clothes_${gender === 1 ? "f" : "m"}_` + key);
      console.log(object.name, entryMeshIndex);
      if (entryMeshIndex === -1) {
        mesh.visible = false;
        return;
      } else {
        mesh.visible = true;
      }
      promises.push(new Promise(async (resolve) => {
        const shirtTexture = await loadClothingTexture(entry[list[entryMeshIndex]]);
        const params = {
          ...clothesModulate,
          map: shirtTexture
        };
        const newBodyMat = new originalMaterial(params);
        mesh.material = newBodyMat;
        resolve();
      }));
    });
    await Promise.all(promises);
    console.log("doneloading");
  }
  nBodyMat.dispose();
  nLegsMat.dispose();
}

