class SoundManager {
  soundBufs;
  audioContext;
  gainNode;
  muted;
  previousVolume;
  constructor() {
    this.soundBufs = {};
    this.audioContext = new (window.AudioContext || window.webkitAudioContext);
    this.gainNode = this.audioContext.createGain();
    this.gainNode.connect(this.audioContext.destination);
    this.muted = false;
    this.previousVolume = 0.28;
    this.queue = new Set;
    const theme = document.documentElement.dataset.theme;
    let currentTheme = theme;
    document.addEventListener("theme-change", () => {
      const theme = document.documentElement.dataset.theme;
      if (theme !== currentTheme) {
        loadBaseSounds("./assets/audio/miiMakerSwitch.zip");
        this.previousVolume = 0.28;
        this.setVolume(0.28);
        this.previousVolume = 0.28;
      }
      currentTheme = theme;
    });
  }
  async loadSound(url, name) {
    const response = await fetch(url);
    const arrayBuffer = await response.arrayBuffer();
    const audioBuffer = await this.audioContext.decodeAudioData(arrayBuffer);
    this.soundBufs[name] = audioBuffer;
  }
  async loadSoundBuffer(arrayBuffer, name) {
    const audioBuffer = await this.audioContext.decodeAudioData(arrayBuffer);
    this.soundBufs[name] = audioBuffer;
  }
  queue;
  playSound(name) {
    const soundBuffer = this.soundBufs[name];
    if (!soundBuffer) {
      console.error(`Sound "${name}" not found.`);
      return;
    }
    if (this.queue.has(name))
      return;
    const source = this.audioContext.createBufferSource();
    source.buffer = soundBuffer;
    source.connect(this.gainNode);
    source.start();
    this.queue.add(name);
    setTimeout(() => {
      this.queue.delete(name);
    }, 50);
  }
  setVolume(volume) {
    if (this.muted)
      return;
    this.gainNode.gain.value = volume;
  }
  mute() {
    if (this.muted)
      return;
    this.previousVolume = this.gainNode.gain.value;
    this.setVolume(0);
    this.muted = true;
  }
  unmute() {
    if (this.muted === false)
      return;
    this.muted = false;
    this.setVolume(this.previousVolume);
  }
}
